export type MaterialLine = {
  key: string; label: string; price: number; unit: string;
  source: string; group: string; url: string;
};

/** Every material, priced with the platform owner's number when they set one. */
export function repairMaterials(overrides: Record<string, number> = {}): MaterialLine[] {
  return REPAIR_MATERIALS.map((m) => {
    const key = m[0] as string;
    const o = overrides[key];
    return {
      key,
      label: m[1] as string,
      price: typeof o === "number" && Number.isFinite(o) ? o : (m[2] as number),
      unit: m[3] as string,
      source: m[4] as string,
      group: m[5] as string,
      url: m[6] as string,
    };
  });
}

/** One material by key, the owner's number first. null when the key is unknown. */
export function materialPrice(key: string, overrides: Record<string, number> = {}): MaterialLine | null {
  return repairMaterials(overrides).find((m) => m.key === key) ?? null;
}
